(r, big) => {
  const n = big ? 20000 : r.int(1, 5), A = big ? "abcdefghijklmnopqrstuvwxyz" : r.pick(["ab", "abc"]);
  const s = r.str(n, A);
  const t = s.split("");
  const k = r.int(0, 3);
  if (k === 1 && n >= 2) { const i = r.int(0, n - 1), j = r.int(0, n - 1); [t[i], t[j]] = [t[j], t[i]]; }
  else if (k === 2) t[r.int(0, n - 1)] = r.str(1, A);
  else if (k === 3) return [s, r.str(r.int(1, big ? 20000 : 5), A)];
  return [s, t.join("")];
}

