function oneSwapMatches(s: string, target: string): boolean {
  if (s.length !== target.length) return false;
  const a = s.split("");
  for (let i = 0; i < a.length; i++) {
    for (let j = i + 1; j < a.length; j++) {
      [a[i], a[j]] = [a[j], a[i]];
      if (a.join("") === target) return true;
      [a[i], a[j]] = [a[j], a[i]];
    }
  }
  return false;
}

