function oneSwapMatches(s: string, target: string): boolean {
  if (s.length !== target.length) return false;
  if (s === target) return new Set(s).size < s.length;
  const diff: number[] = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== target[i]) {
      diff.push(i);
      if (diff.length > 2) return false;
    }
  }
  if (diff.length !== 2) return false;
  const [i, j] = diff;
  return s[i] === target[j] && s[j] === target[i];
}

